//! Action classifier: maps `(method, host, path)` to an action class.
//!
//! See `README.md` for the specification. The two public functions below are
//! the fixed API; everything else in this crate is yours to design.

mod config;

use config::parse;

/// Action classes a rule may name. A rule naming anything else is invalid.
pub const ACTION_CLASSES: &[&str] = &[
    "payment.read",
    "payment.create",
    "payment.refund",
    "repo.read",
    "repo.write",
    "communication.external.send",
    "llm.inference",
];

#[derive(Debug, thiserror::Error)]
pub enum LoadError {
    #[error("invalid TOML: {0}")]
    Toml(#[from] toml::de::Error),
    #[error("unsupported format version {0}; expected 1")]
    UnsupportedFormatVersion(u32),
    #[error("{0} must not be empty or malformed")]
    InvalidField(&'static str),
    #[error("rule {rule} has an invalid {field}")]
    InvalidRule { rule: usize, field: &'static str },
    #[error("rule {rule} names unsupported action class {action_class:?}")]
    UnknownActionClass { rule: usize, action_class: String },
    #[error("ambiguous rules match the same request with different action classes")]
    AmbiguousRules,
}

/// A validated, ready-to-query collection of mapping sets.
pub struct Classifier {
    rules: Vec<CompiledRule>,
}

struct CompiledRule {
    method: Option<String>,
    host: String,
    path: Option<String>,
    action_class: String,
}

/// Parse, validate and combine mapping sets. Each item is the text of one
/// user-provided mapping file.
pub async fn load(sets: &[&str]) -> Result<Classifier, LoadError> {
    let mut rules = Vec::new();
    for input in sets {
        let set = parse(input)?;
        for rule in set.rules {
            let host = match rule.subdomain.as_deref() {
                None => set.host.clone(),
                Some("*") => format!("*.{}", set.host),
                Some(subdomain) => format!("{subdomain}.{}", set.host),
            }
            .to_ascii_lowercase();
            rules.push(CompiledRule {
                method: rule.method,
                host,
                path: rule.path,
                action_class: rule.action_class,
            });
        }
    }
    Ok(Classifier { rules })
}

impl Classifier {
    /// Classify one request. Returns `None` when it is unclassified.
    pub async fn classify(&self, method: &str, host: &str, path: &str) -> Option<&str> {
        let normalized_host = host.trim_end_matches('.').to_ascii_lowercase();
        self.rules
            .iter()
            .filter(|rule| matches(rule, method, &normalized_host, path))
            .max_by_key(|rule| specificity(rule))
            .map(|rule| rule.action_class.as_str())
    }
}

fn matches(rule: &CompiledRule, method: &str, host: &str, path: &str) -> bool {
    rule.method
        .as_deref()
        .is_none_or(|expected| expected == method)
        && host_matches(&rule.host, host)
        && rule
            .path
            .as_deref()
            .is_none_or(|pattern| glob_matches(pattern, path))
}

fn host_matches(pattern: &str, host: &str) -> bool {
    if let Some(suffix) = pattern.strip_prefix("*.") {
        host.strip_suffix(suffix)
            .is_some_and(|prefix| prefix.ends_with('.') && prefix.len() > 1)
    } else {
        pattern.eq_ignore_ascii_case(host)
    }
}

fn glob_matches(pattern: &str, value: &str) -> bool {
    let mut remainder = value;
    let mut first = true;
    for part in pattern.split('*') {
        if part.is_empty() {
            continue;
        }
        let Some(index) = remainder.find(part) else {
            return false;
        };
        if first && !pattern.starts_with('*') && index != 0 {
            return false;
        }
        remainder = &remainder[index + part.len()..];
        first = false;
    }
    pattern.ends_with('*') || remainder.is_empty()
}

fn specificity(rule: &CompiledRule) -> (u8, u8, usize, usize) {
    let host = if rule.host.starts_with("*.") { 1 } else { 2 };
    let method = u8::from(rule.method.is_some());
    let path = rule.path.as_ref().map_or((0, 0), |path| {
        (u8::from(!path.contains('*')), path.replace('*', "").len())
    });
    (host, method, path.0 as usize, path.1)
}
//! Parsing and validation for mapping-set TOML documents.

use serde::Deserialize;

use crate::{ACTION_CLASSES, LoadError};

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct MappingSet {
    pub(crate) format_version: u32,
    pub(crate) name: String,
    pub(crate) description: String,
    pub(crate) host: String,
    #[serde(default)]
    pub(crate) rules: Vec<Rule>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct Rule {
    pub(crate) method: Option<String>,
    pub(crate) subdomain: Option<String>,
    pub(crate) path: Option<String>,
    pub(crate) action_class: String,
}

/// Converts one TOML document to a checked mapping set.
pub(crate) fn parse(input: &str) -> Result<MappingSet, LoadError> {
    let set: MappingSet = toml::from_str(input).map_err(LoadError::Toml)?;
    validate(&set)?;
    Ok(set)
}

fn validate(set: &MappingSet) -> Result<(), LoadError> {
    if set.format_version != 1 {
        return Err(LoadError::UnsupportedFormatVersion(set.format_version));
    }
    required_text("name", &set.name)?;
    required_text("description", &set.description)?;
    validate_host(&set.host)?;

    for (index, rule) in set.rules.iter().enumerate() {
        if !ACTION_CLASSES.contains(&rule.action_class.as_str()) {
            return Err(LoadError::UnknownActionClass {
                rule: index,
                action_class: rule.action_class.clone(),
            });
        }
        if let Some(method) = &rule.method {
            if method.is_empty() || !method.bytes().all(is_http_token) {
                return Err(LoadError::InvalidRule {
                    rule: index,
                    field: "method",
                });
            }
        }
        if let Some(subdomain) = &rule.subdomain {
            if subdomain != "*" && !is_dns_name(subdomain) {
                return Err(LoadError::InvalidRule {
                    rule: index,
                    field: "subdomain",
                });
            }
        }
        if let Some(path) = &rule.path {
            if !path.starts_with('/') {
                return Err(LoadError::InvalidRule {
                    rule: index,
                    field: "path",
                });
            }
        }
    }
    Ok(())
}

fn required_text(field: &'static str, value: &str) -> Result<(), LoadError> {
    if value.trim().is_empty() {
        Err(LoadError::InvalidField(field))
    } else {
        Ok(())
    }
}

fn validate_host(host: &str) -> Result<(), LoadError> {
    if is_dns_name(host) {
        Ok(())
    } else {
        Err(LoadError::InvalidField("host"))
    }
}

fn is_dns_name(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 253
        && value.split('.').all(|label| {
            !label.is_empty()
                && label.len() <= 63
                && !label.starts_with('-')
                && !label.ends_with('-')
                && label
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
        })
}

fn is_http_token(byte: u8) -> bool {
    byte.is_ascii_alphanumeric()
        || matches!(
            byte,
            b'!' | b'#'
                | b'$'
                | b'%'
                | b'&'
                | b'\''
                | b'*'
                | b'+'
                | b'-'
                | b'.'
                | b'^'
                | b'_'
                | b'`'
                | b'|'
                | b'~'
        )
}

#[cfg(test)]
mod tests {
    use super::parse;

    const VALID: &str = r#"
format_version = 1
name = "Acme"
description = "Acme API"
host = "acme.com"

[[rules]]
action_class = "payment.read"
"#;

    #[test]
    fn parses_a_valid_mapping_set() {
        let set = parse(VALID).unwrap();
        assert_eq!(set.host, "acme.com");
        assert_eq!(set.rules.len(), 1);
    }

    #[test]
    fn rejects_missing_required_top_level_fields() {
        for field in [
            "format_version = 1\n",
            "name = \"Acme\"\n",
            "description = \"Acme API\"\n",
            "host = \"acme.com\"\n",
        ] {
            let input = VALID.replace(field, "");
            assert!(parse(&input).is_err(), "expected {field:?} to be required");
        }
    }

    #[test]
    fn rejects_unknown_top_level_and_rule_keys() {
        assert!(parse(&format!("{VALID}\nowner = \"ops\"\n")).is_err());
        assert!(parse(&VALID.replace("action_class", "action_clas")).is_err());
    }

    #[test]
    fn rejects_unknown_action_classes_and_invalid_values() {
        assert!(parse(&VALID.replace("payment.read", "payments.delete")).is_err());
        assert!(
            parse(&VALID.replace("host = \"acme.com\"", "host = \"https://acme.com\"")).is_err()
        );
        assert!(
            parse(&VALID.replace(
                "action_class = \"payment.read\"",
                "path = \"relative\"\naction_class = \"payment.read\""
            ))
            .is_err()
        );
    }

    #[test]
    fn rejects_unsupported_versions_and_missing_rule_action_classes() {
        assert!(parse(&VALID.replace("format_version = 1", "format_version = 2")).is_err());
        assert!(
            parse(&VALID.replace("action_class = \"payment.read\"", "path = \"/v1\"")).is_err()
        );
    }

    #[test]
    fn rejects_empty_and_malformed_matcher_values() {
        assert!(parse(&VALID.replace("name = \"Acme\"", "name = \"  \"")).is_err());
        assert!(
            parse(&VALID.replace(
                "action_class = \"payment.read\"",
                "method = \"GET /\"\naction_class = \"payment.read\""
            ))
            .is_err()
        );
        assert!(
            parse(&VALID.replace(
                "action_class = \"payment.read\"",
                "subdomain = \"api..internal\"\naction_class = \"payment.read\""
            ))
            .is_err()
        );
    }

    #[test]
    fn accepts_optional_rule_matchers() {
        let input = VALID.replace("action_class = \"payment.read\"", "method = \"PATCH\"\nsubdomain = \"*\"\npath = \"/v1/*\"\naction_class = \"payment.read\"");
        assert!(parse(&input).is_ok());
    }
}
//! Example tests that ship with the starter. They show the API in use.

use action_classifier::load;

const ACME: &str = r#"
format_version = 1
name = "Acme Payments"
description = "Acme payments API"
host = "acme.com"

[[rules]]
method = "GET"
subdomain = "api"
path = "/v1/payment_intents"
action_class = "payment.read"

[[rules]]
subdomain = "api"
path = "/v1/refunds/*"
action_class = "payment.refund"

[[rules]]
path = "/pricing"
action_class = "payment.read"
"#;

#[tokio::test]
async fn exact_rule_matches() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("GET", "api.acme.com", "/v1/payment_intents")
            .await,
        Some("payment.read")
    );
}

#[tokio::test]
async fn method_less_rule_matches_any_method() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("DELETE", "api.acme.com", "/v1/refunds/re_1")
            .await,
        Some("payment.refund")
    );
}

#[tokio::test]
async fn rule_without_subdomain_applies_to_the_host_itself() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("GET", "acme.com", "/pricing").await,
        Some("payment.read")
    );
}

#[tokio::test]
async fn unmatched_request_is_unclassified() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("GET", "api.acme.com", "/v2/anything").await,
        None
    );
}
