    fn detects_equal_specificity_overlaps_only() {
        let conflicting = vec![rule(Some("api"), None, Some("/v1/*"), "payment.read"), rule(Some("api"), None, Some("/v1/**"), "payment.refund")];
        assert_eq!(find_conflict(&conflicting), Some((0, 1)));
        let ordered = vec![rule(Some("api"), None, Some("/v1/*"), "payment.read"), rule(Some("api"), None, Some("/v1/payments"), "payment.refund")];
