//! Canonicalization for the three request components accepted by the classifier.
//!
//! This module deliberately accepts only the unambiguous ASCII subset of HTTP
//! authority and path syntax. In particular, IP literals, userinfo, encoded
//! separators, malformed percent escapes, and non-ASCII text are rejected.

/// Returns a lowercase DNS hostname without one optional trailing dot or port.
pub(crate) fn host(input: &str) -> Option<String> {
    if input.is_empty() || !input.is_ascii() || input.contains('@') {
        return None;
    }

    let (name, port) = match input.rsplit_once(':') {
        Some((name, port)) => (name, Some(port)),
        None => (input, None),
    };
    // Parsing also rejects values outside the TCP/UDP port range.
    if let Some(port) = port
        && (!port.bytes().all(|byte| byte.is_ascii_digit()) || port.parse::<u16>().is_err())
    {
        return None;
    }

    let name = name.strip_suffix('.').unwrap_or(name);
    if !is_dns_name(name) || name.parse::<std::net::Ipv4Addr>().is_ok() {
        return None;
    }
    Some(name.to_ascii_lowercase())
}

/// Validates an HTTP token and upper-cases it. Methods are case-sensitive on
/// the wire, but clients (Fetch, Node) upper-case common methods and some
/// servers fold case. Folding here keeps `delete` from slipping past a
/// `DELETE` rule into a broader method-less one.
pub(crate) fn method(input: &str) -> Option<String> {
    (!input.is_empty() && input.bytes().all(is_http_token)).then(|| input.to_ascii_uppercase())
}

/// Normalizes a request path. Empty input represents the origin-form `/`.
pub(crate) fn request_path(input: &str) -> Option<String> {
    let end = input.find(['?', '#']).unwrap_or(input.len());
    let path = &input[..end];
    if path.is_empty() {
        return Some("/".into());
    }
    normalize_path(path, false)
}

/// Normalizes a configuration path pattern while retaining literal `*`
/// wildcards. Query strings and fragments never reach the matcher, so a
/// pattern containing one is a configuration mistake.
pub(crate) fn pattern_path(input: &str) -> Option<String> {
    if input.contains(['?', '#']) {
        return None;
    }
    normalize_path(input, true)
}

/// Canonical form shared by requests and patterns: unreserved percent escapes
/// decoded, other escapes upper-cased, dot segments removed. Empty segments
/// (`//`), backslashes, and encoded separators are rejected because servers
/// disagree on what they mean.
fn normalize_path(input: &str, pattern: bool) -> Option<String> {
    if !input.starts_with('/') {
        return None;
    }
    let decoded = decode_unreserved(input)?;
    if decoded.contains("//") {
        return None;
    }

    // A dot segment next to a wildcard cannot be canonicalized soundly: the
    // wildcard can span an unknown number of path segments. Reject rather than
    // assigning it a meaning that a URL client or server may not share.
    if pattern
        && decoded.contains('*')
        && decoded
            .split('/')
            .any(|segment| segment == "." || segment == "..")
    {
        return None;
    }
    Some(remove_dot_segments(&decoded))
}

/// RFC 3986 section 6.2.2 normalization: `%72` and `r` are the same path, so
/// decode escaped unreserved bytes and upper-case the rest. Decoding happens
/// once; `%25` stays `%25`.
fn decode_unreserved(input: &str) -> Option<String> {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let bytes = input.as_bytes();
    let mut output = String::with_capacity(input.len());
    let mut index = 0;
    while let Some(&byte) = bytes.get(index) {
        if byte == b'%' {
            let hi = hex(*bytes.get(index + 1)?)?;
            let lo = hex(*bytes.get(index + 2)?)?;
            let value = (hi << 4) | lo;
            if matches!(value, b'/' | b'\\') {
                return None;
            }
            if value.is_ascii_alphanumeric() || matches!(value, b'-' | b'.' | b'_' | b'~') {
                output.push(char::from(value));
            } else {
                output.push('%');
                output.push(char::from(HEX[usize::from(hi)]));
                output.push(char::from(HEX[usize::from(lo)]));
            }
            index += 3;
        } else {
            if !byte.is_ascii_graphic() || byte == b'\\' {
                return None;
            }
            output.push(char::from(byte));
            index += 1;
        }
    }
    Some(output)
}

fn hex(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

/// RFC 3986 dot-segment removal for an absolute path without empty segments.
/// A stack keeps this linear in the path length.
fn remove_dot_segments(input: &str) -> String {
    let mut segments = Vec::new();
    // A path ending in `.` or `..` names a directory, as `/a/b/..` -> `/a/`.
    let mut trailing_slash = false;
    for segment in input.split('/').skip(1) {
        match segment {
            "." => trailing_slash = true,
            ".." => {
                segments.pop();
                trailing_slash = true;
            }
            _ => {
                segments.push(segment);
                trailing_slash = false;
            }
        }
    }
    let mut output = format!("/{}", segments.join("/"));
    if trailing_slash && !output.ends_with('/') {
        output.push('/');
    }
    output
}

fn is_dns_name(value: &str) -> bool {
    !value.is_empty()
        && value.len() <= 253
        && value.split('.').all(|label| {
            !label.is_empty()
                && label.len() <= 63
                && !label.starts_with('-')
                && !label.ends_with('-')
                && label
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
        })
}

fn is_http_token(byte: u8) -> bool {
    byte.is_ascii_alphanumeric()
        || matches!(
            byte,
            b'!' | b'#'
                | b'$'
                | b'%'
                | b'&'
                | b'\''
                | b'*'
                | b'+'
                | b'-'
                | b'.'
                | b'^'
                | b'_'
                | b'`'
                | b'|'
                | b'~'
        )
}

#[cfg(test)]
mod tests {
    use super::{host, method, pattern_path, request_path};

    #[test]
    fn normalizes_hosts_and_rejects_ambiguous_authorities() {
        assert_eq!(host("API.Acme.COM.:443"), Some("api.acme.com".into()));
        for value in [
            "",
            "acme.com:",
            "acme.com:99999",
            "u@acme.com",
            "192.0.2.1",
            "[::1]",
            "acme..com",
            "é.com",
            "acme.com..",
        ] {
            assert_eq!(host(value), None, "{value}");
        }
    }

    #[test]
    fn methods_are_tokens_folded_to_upper_case() {
        assert_eq!(method("GET"), Some("GET".into()));
        assert_eq!(method("delete"), Some("DELETE".into()));
        assert_eq!(method("Patch"), Some("PATCH".into()));
        for value in ["", "GET ", "GET\n", "é"] {
            assert_eq!(method(value), None, "{value:?}");
        }
    }

    #[test]
    fn paths_strip_query_and_normalize_dot_segments() {
        assert_eq!(request_path(""), Some("/".into()));
        assert_eq!(request_path("/v1/../admin?q=1#x"), Some("/admin".into()));
        assert_eq!(request_path("/v1/%2e%2e/admin"), Some("/admin".into()));
        assert_eq!(request_path("/a/b/.."), Some("/a/".into()));
        assert_eq!(request_path("/a/./b/."), Some("/a/b/".into()));
        assert_eq!(request_path("/../../x"), Some("/x".into()));
        assert_eq!(request_path("/v1/payments/"), Some("/v1/payments/".into()));
        for value in [
            "relative", "/x%ZZ", "/x%2f", "/x%5C", "/x\\y", "/é", "/a b", "/a\0", "/v1//x", "//",
        ] {
            assert_eq!(request_path(value), None, "{value:?}");
        }
    }

    #[test]
    fn paths_decode_unreserved_escapes_only() {
        assert_eq!(request_path("/v1/%72efunds"), Some("/v1/refunds".into()));
        assert_eq!(request_path("/%7Euser/%5f"), Some("/~user/_".into()));
        assert_eq!(request_path("/a%3a%2A"), Some("/a%3A%2A".into()));
        // No double decoding: `%252e` is a literal `%2e`, not a dot segment.
        assert_eq!(
            request_path("/a/%252e%252e/b"),
            Some("/a/%252e%252e/b".into())
        );
    }

    #[test]
    fn patterns_retain_wildcards_but_reject_ambiguous_dot_patterns() {
        assert_eq!(
            pattern_path("/v1/*/refunds/**"),
            Some("/v1/*/refunds/**".into())
        );
        assert_eq!(
            pattern_path("/v1/%72efunds/*"),
            Some("/v1/refunds/*".into())
        );
        assert_eq!(pattern_path("/v1/*/../admin"), None);
        assert_eq!(pattern_path("/v1/*?debug=true"), None);
        assert_eq!(pattern_path("/v1//x"), None);
    }

    #[test]
    fn long_and_arbitrary_utf8_request_inputs_never_panic() {
        assert!(request_path(&format!("/{}", "a".repeat(32 * 1024))).is_some());
        for value in ["\0", "\u{10ffff}", "/\u{10ffff}", "/%"] {
            assert_eq!(request_path(value), None, "{value:?}");
        }
    }
}
//! Compiled-rule matching, lexicographic specificity, and load-time conflicts.

use std::cmp::Ordering;

use crate::normalize;

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum HostPattern {
    Bare(String),
    Exact(String),
    AnySubdomain(String),
}

#[derive(Debug, Clone)]
pub(crate) struct CompiledRule {
    pub(crate) method: Option<String>,
    pub(crate) host: HostPattern,
    pub(crate) path: Option<String>,
    pub(crate) action_class: String,
    specificity: Specificity,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct Specificity {
    host: u8,
    path_kind: u8,
    literal_count: usize,
    inverted_wildcard_count: usize,
    literal_prefix: usize,
    method: u8,
}

impl Ord for Specificity {
    fn cmp(&self, other: &Self) -> Ordering {
        (
            self.host,
            self.path_kind,
            self.literal_count,
            self.inverted_wildcard_count,
            self.literal_prefix,
            self.method,
        )
            .cmp(&(
                other.host,
                other.path_kind,
                other.literal_count,
                other.inverted_wildcard_count,
                other.literal_prefix,
                other.method,
            ))
    }
}

impl PartialOrd for Specificity {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

#[derive(Debug)]
pub(crate) enum CompileError {
    Host,
    Method,
    Path,
}

impl CompiledRule {
    pub(crate) fn new(
        method: Option<&str>,
        base_host: &str,
        subdomain: Option<&str>,
        path: Option<&str>,
        action_class: String,
    ) -> Result<Self, CompileError> {
        let base_host = normalize::host(base_host).ok_or(CompileError::Host)?;
        let host = match subdomain {
            None => HostPattern::Bare(base_host),
            Some("*") => HostPattern::AnySubdomain(base_host),
            Some(value) => {
                let value = normalize::host(value).ok_or(CompileError::Host)?;
                HostPattern::Exact(format!("{value}.{base_host}"))
            }
        };
        let method = match method {
            Some(value) => Some(normalize::method(value).ok_or(CompileError::Method)?),
            None => None,
        };
        let path = match path {
            Some(value) => Some(normalize::pattern_path(value).ok_or(CompileError::Path)?),
            None => None,
        };
        let specificity = specificity(&host, method.is_some(), path.as_deref());
        Ok(Self {
            method,
            host,
            path,
            action_class,
            specificity,
        })
    }

    pub(crate) fn matches(&self, method: &str, host: &str, path: &str) -> bool {
        self.method
            .as_deref()
            .is_none_or(|expected| expected == method)
            && host_matches(&self.host, host)
            && self
                .path
                .as_deref()
                .is_none_or(|pattern| glob_matches(pattern, path))
    }

    pub(crate) fn compare_specificity(&self, other: &Self) -> Ordering {
        self.specificity.cmp(&other.specificity)
    }
}

pub(crate) fn find_conflict(rules: &[CompiledRule]) -> Option<(usize, usize)> {
    for (right_index, right) in rules.iter().enumerate() {
        for (left_index, left) in rules[..right_index].iter().enumerate() {
            if left.action_class != right.action_class
                && left.specificity == right.specificity
                && methods_overlap(left.method.as_deref(), right.method.as_deref())
                && hosts_overlap(&left.host, &right.host)
                && paths_overlap(left.path.as_deref(), right.path.as_deref())
            {
                return Some((left_index, right_index));
            }
        }
    }
    None
}

fn specificity(host: &HostPattern, has_method: bool, path: Option<&str>) -> Specificity {
    let host = u8::from(!matches!(host, HostPattern::AnySubdomain(_)));
    let (path_kind, literal_count, wildcard_count, literal_prefix) = match path {
        None => (0, 0, 0, 0),
        Some(value) if !value.contains('*') => (2, value.len(), 0, value.len()),
        Some(value) => (
            1,
            value.bytes().filter(|byte| *byte != b'*').count(),
            value.bytes().filter(|byte| *byte == b'*').count(),
            value.find('*').unwrap_or(0),
        ),
    };
    Specificity {
        host,
        path_kind,
        literal_count,
        inverted_wildcard_count: usize::MAX - wildcard_count,
        literal_prefix,
        method: u8::from(has_method),
    }
}

fn host_matches(pattern: &HostPattern, host: &str) -> bool {
    match pattern {
        HostPattern::Bare(expected) | HostPattern::Exact(expected) => expected == host,
        HostPattern::AnySubdomain(base) => host
            .strip_suffix(base)
            .is_some_and(|prefix| prefix.ends_with('.') && prefix.len() > 1),
    }
}

fn methods_overlap(left: Option<&str>, right: Option<&str>) -> bool {
    left.is_none() || right.is_none() || left == right
}

fn hosts_overlap(left: &HostPattern, right: &HostPattern) -> bool {
    match (left, right) {
        (HostPattern::Bare(a), HostPattern::Bare(b))
        | (HostPattern::Bare(a), HostPattern::Exact(b))
        | (HostPattern::Exact(a), HostPattern::Bare(b))
        | (HostPattern::Exact(a), HostPattern::Exact(b)) => a == b,
        // These pairs cannot have equal host specificity, but retain correct
        // overlap semantics for callers that want them.
        (HostPattern::AnySubdomain(base), HostPattern::Bare(host))
        | (HostPattern::Bare(host), HostPattern::AnySubdomain(base))
        | (HostPattern::AnySubdomain(base), HostPattern::Exact(host))
        | (HostPattern::Exact(host), HostPattern::AnySubdomain(base)) => {
            host_matches(&HostPattern::AnySubdomain(base.clone()), host)
        }
        (HostPattern::AnySubdomain(a), HostPattern::AnySubdomain(b)) => {
            a == b || a.ends_with(&format!(".{b}")) || b.ends_with(&format!(".{a}"))
        }
    }
}

fn paths_overlap(left: Option<&str>, right: Option<&str>) -> bool {
    match (left, right) {
        (None, _) | (_, None) => true,
        (Some(left), Some(right)) => globs_overlap(left, right),
    }
}

pub(crate) fn glob_matches(pattern: &str, value: &str) -> bool {
    let pattern = pattern.as_bytes();
    let value = value.as_bytes();
    let (mut p, mut v, mut star, mut retry) = (0, 0, None, 0);
    while v < value.len() {
        while p < pattern.len() && pattern[p] == b'*' {
            star = Some(p);
            p += 1;
            retry = v;
        }
        if p < pattern.len() && pattern[p] == value[v] {
            p += 1;
            v += 1;
        } else if let Some(star_index) = star {
            p = star_index + 1;
            retry += 1;
            v = retry;
        } else {
            return false;
        }
    }
    while p < pattern.len() && pattern[p] == b'*' {
        p += 1;
    }
    p == pattern.len()
}

/// Product traversal of two `*` glob NFAs. The sentinel represents any byte
/// not currently present as a literal and keeps the alphabet finite.
fn globs_overlap(left: &str, right: &str) -> bool {
    let (left, right) = (left.as_bytes(), right.as_bytes());
    let mut seen = vec![vec![false; right.len() + 1]; left.len() + 1];
    let mut queue = std::collections::VecDeque::from([(0usize, 0usize)]);
    while let Some((i, j)) = queue.pop_front() {
        if seen[i][j] {
            continue;
        }
        seen[i][j] = true;
        if i == left.len() && j == right.len() {
            return true;
        }
        if left.get(i) == Some(&b'*') {
            queue.push_back((i + 1, j));
        }
        if right.get(j) == Some(&b'*') {
            queue.push_back((i, j + 1));
        }
        let mut alphabet = vec![0];
        if let Some(&byte) = left.get(i).filter(|&&byte| byte != b'*') {
            alphabet.push(byte);
        }
        if let Some(&byte) = right.get(j).filter(|&&byte| byte != b'*') {
            alphabet.push(byte);
        }
        for byte in alphabet {
            let next_left = transition(left, i, byte);
            let next_right = transition(right, j, byte);
            if let (Some(next_left), Some(next_right)) = (next_left, next_right) {
                queue.push_back((next_left, next_right));
            }
        }
    }
    false
}

fn transition(pattern: &[u8], index: usize, byte: u8) -> Option<usize> {
    match pattern.get(index) {
        Some(b'*') => Some(index),
        Some(&literal) if literal == byte => Some(index + 1),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::{CompiledRule, find_conflict, glob_matches};

    fn rule(
        subdomain: Option<&str>,
        method: Option<&str>,
        path: Option<&str>,
        action: &str,
    ) -> CompiledRule {
        CompiledRule::new(method, "acme.com", subdomain, path, action.into()).unwrap()
    }

    #[test]
    fn wildcard_hosts_respect_boundaries_and_nested_subdomains() {
        let rule = rule(Some("*"), None, None, "payment.read");
        assert!(rule.matches("GET", "a.b.acme.com", "/"));
        assert!(!rule.matches("GET", "acme.com", "/"));
        assert!(!rule.matches("GET", "evilacme.com", "/"));
    }

    #[test]
    fn globs_match_zero_or_more_characters() {
        assert!(glob_matches("/v1/refunds/*", "/v1/refunds/"));
        assert!(glob_matches("/v1/*/x/*", "/v1/a/b/x/c"));
        assert!(!glob_matches("/v1/refunds/*", "/v1/refunds"));
        assert!(glob_matches("/**/**/**", "/a/b/c/d"));
    }

    #[test]
    fn specificity_is_lexicographic() {
        let exact_host = rule(Some("api"), None, Some("/v1/*"), "payment.read");
        let wildcard_host = rule(
            Some("*"),
            Some("GET"),
            Some("/v1/payments"),
            "payment.create",
        );
        assert!(exact_host.compare_specificity(&wildcard_host).is_gt());
        let exact_path = rule(Some("api"), None, Some("/v1/payments"), "payment.read");
        assert!(exact_path.compare_specificity(&exact_host).is_gt());
    }

    #[test]
    fn detects_equal_specificity_overlaps_only() {
        let conflicting = vec![
            rule(Some("api"), None, Some("/v1/*a*bc"), "payment.read"),
            rule(Some("api"), None, Some("/v1/*ab*c"), "payment.refund"),
        ];
        assert_eq!(find_conflict(&conflicting), Some((0, 1)));
        let ordered = vec![
            rule(Some("api"), None, Some("/v1/*"), "payment.read"),
            rule(Some("api"), None, Some("/v1/payments"), "payment.refund"),
        ];
        assert_eq!(find_conflict(&ordered), None);
    }

    #[test]
    fn explicit_methods_win_only_after_host_and_path_ties() {
        let any_method = rule(Some("api"), None, Some("/v1/*"), "payment.read");
        let get = rule(Some("api"), Some("GET"), Some("/v1/*"), "payment.create");
        assert!(get.compare_specificity(&any_method).is_gt());
        assert!(get.matches("GET", "api.acme.com", "/v1/x"));
        assert!(!get.matches("POST", "api.acme.com", "/v1/x"));
        let lower = rule(Some("api"), Some("get"), Some("/v1/*"), "payment.create");
        assert_eq!(lower.method.as_deref(), Some("GET"));
    }
}
//! Requests that spell the same operation differently must not reach a
//! broader, less sensitive rule than the canonical spelling does.

use action_classifier::load;

const ACME: &str = r#"
format_version = 1
name = "Acme Payments"
description = "Acme payments API"
host = "acme.com"

[[rules]]
subdomain = "api"
path = "/v1/*"
action_class = "payment.read"

[[rules]]
subdomain = "api"
path = "/v1/refunds/*"
action_class = "payment.refund"

[[rules]]
subdomain = "api"
method = "DELETE"
path = "/v1/charges/*"
action_class = "payment.refund"

[[rules]]
subdomain = "api"
path = "/v1/payouts"
action_class = "payment.create"
"#;

#[tokio::test]
async fn percent_encoded_unreserved_characters_match_their_decoded_form() {
    let c = load(&[ACME]).await.unwrap();
    for path in [
        "/v1/%72efunds/x",
        "/v1/%72%65%66%75%6E%64%73/x",
        "/v1/refunds/%78",
    ] {
        assert_eq!(
            c.classify("POST", "api.acme.com", path).await,
            Some("payment.refund"),
            "{path}"
        );
    }
}

#[tokio::test]
async fn method_case_does_not_fall_through_to_method_less_rule() {
    let c = load(&[ACME]).await.unwrap();
    for method in ["DELETE", "delete", "Delete"] {
        assert_eq!(
            c.classify(method, "api.acme.com", "/v1/charges/ch_1").await,
            Some("payment.refund"),
            "{method}"
        );
    }
}

#[tokio::test]
async fn empty_path_segments_are_unclassified() {
    let c = load(&[ACME]).await.unwrap();
    for path in ["/v1//refunds/x", "//v1/refunds/x", "/v1/refunds//x"] {
        assert_eq!(
            c.classify("POST", "api.acme.com", path).await,
            None,
            "{path}"
        );
    }
}

#[tokio::test]
async fn trailing_slash_that_changes_the_class_is_unclassified() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/payouts").await,
        Some("payment.create")
    );
    // `/v1/payouts/` alone would match `/v1/*` (payment.read).
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/payouts/").await,
        None
    );
    // No disagreement: both spellings are payment.read.
    assert_eq!(
        c.classify("GET", "api.acme.com", "/v1/balance/").await,
        Some("payment.read")
    );
}

#[tokio::test]
async fn dot_segments_resolve_before_matching() {
    let c = load(&[ACME]).await.unwrap();
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/balance/../refunds/x")
            .await,
        Some("payment.refund")
    );
    assert_eq!(
        c.classify("POST", "api.acme.com", "/v1/balance/%2e%2e/refunds/x")
            .await,
        Some("payment.refund")
    );
}

#[tokio::test]
async fn ambiguous_or_malformed_paths_are_unclassified() {
    let c = load(&[ACME]).await.unwrap();
    for path in [
        "/v1/refunds%2fx",
        "/v1\\refunds\\x",
        "/v1/refunds/%zz",
        "/v1/re funds/x",
    ] {
        assert_eq!(
            c.classify("POST", "api.acme.com", path).await,
            None,
            "{path:?}"
        );
    }
}

#[tokio::test]
async fn empty_rules_list_is_rejected() {
    let empty = r#"
format_version = 1
name = "Empty"
description = "No rules"
host = "acme.com"
rules = []
"#;
    assert!(load(&[empty]).await.is_err());
}

